SELECT ground_vehicle_status->'vehicle_motion'->>'speed_kmh', 
       regexp_replace(ground_vehicle_status->'vehicle_motion'->>'speed_kmh', '[^0-9.]', '')::numeric as speed_numeric
FROM "ChassisAndVehicle" LIMIT 5;

SELECT ground_vehicle_status->'vehicle_motion'->>'speed_kmh', 
       (regexp_replace(ground_vehicle_status->'vehicle_motion'->>'speed_kmh', '[^0-9.]', ''))::real as speed_numeric
FROM "ChassisAndVehicle" LIMIT 5;

SELECT ground_vehicle_status->'vehicle_motion'->>'speed_kmh', 
       split_part(ground_vehicle_status->'vehicle_motion'->>'speed_kmh', ' ', 1)::real as speed_numeric
FROM "ChassisAndVehicle" LIMIT 5;

SELECT ground_vehicle_status->'brake_system'->>'pad_wear_pct', 
       ground_vehicle_status->'tracks'->>'wear_pct'
FROM "ChassisAndVehicle" LIMIT 5;

SELECT NULLIF(ground_vehicle_status->'brake_system'->>'pad_wear_pct', 'None')::real as pad_wear,
       NULLIF(ground_vehicle_status->'tracks'->>'wear_pct', 'None')::real as track_wear
FROM "ChassisAndVehicle" LIMIT 5;

